-- 1. List the number of films per category.

select  f.name, count(fc.film_id) as number_of_films
from film_category as fc
join category as f
on fc.category_id = f.category_id
group by fc.category_id, f.name
order by name asc;


-- 2. Retrieve the store ID, city, and country for each store.
select s.store_id, c.city, co.country
from city as c
join address as ad
on ad.city_id = c.city_id
join store as s
on s.address_id = ad.address_id
join country as co
on co.country_id = c.country_id;


-- 3. Calculate the total revenue generated by each store in dollars.
select sta.store_id, sum(p.amount) as total
from staff as sta
join payment as p
on sta.staff_id = p.staff_id
group by sta.store_id;


-- 4. Determine the average running time of films for each category.

select fc.category_id, avg(f.length)
from film as f
join film_category as fc
on f.film_id = fc.film_id
group by fc.category_id;





-- 5. Identify the film categories with the longest average running time.

select fc.category_id, avg(f.length) as average_length
from film as f
join film_category as fc
on f.film_id = fc.film_id
group by fc.category_id
order by average_length desc
limit 5;



-- 6. Display the top 10 most frequently rented movies in descending order.
select f.title, count(i.film_id) as frequency 
from inventory as i
join rental as r
on r.inventory_id = i.inventory_id
join film as f
on i.film_id = f.film_id
group by f.film_id
order by frequency desc
limit 10;


-- 7. Determine if "Academy Dinosaur" can be rented from Store 1.

select title, f.film_id, i.inventory_id, i.store_id
from inventory as i
join film as f
on f.film_id = i.film_id
where store_id = 1 and title = "ACADEMY DINOSAUR";

-- 8. Provide a list of all distinct film titles, along with their availability status in the inventory. Include a column indicating whether each title is 'Available' or 'NOT available.' Note that there are 42 titles that are not in the inventory, and this information can be obtained using a CASE statement combined with IFNULL."

select f.title, i.store_id
from film as f
join inventory as i
on f.film_id = i.film_id
group by title, store_id;

